import { l, type L, type Class9Chapter, type ChoiceTask, type SelectTask, type MatchTask, type OrderTask, type TaskBase } from './types';

const opt = (id: string, label: L, feedback: L) => ({ id, label, feedback });
const row = (id: string, label: L, answer: string, explanation: L) => ({ id, label, answer, explanation });
const scene = (title: L, caption: L, dialogue: L) => ({ title, caption, dialogue });
const base = (prompt: L, context: L, hint: L): TaskBase => ({ prompt, context, hint,
  success: l('The recorded answer meets the supplied requirements. Explain the evidence for your choices.', 'दर्ज जवाब दी गई ज़रूरतें पूरी करता है। अपने चुनावों के सबूत समझाएँ।'),
  correction: l('This answer is incorrect. Read the reasons for the affected items, then revise the record against the supplied facts.', 'यह जवाब गलत है। संबंधित आइटम के कारण पढ़ें, फिर दिए गए तथ्यों के अनुसार रिकॉर्ड सुधारें।'),
});
const choose = (b: TaskBase, options: ChoiceTask['options'], correct: string): ChoiceTask => ({ ...b, kind: 'choice', options, correct });
const select = (b: TaskBase, items: SelectTask['items'], expected: string[]): SelectTask => ({ ...b, kind: 'select', items, expected });
const match = (b: TaskBase, rows: MatchTask['rows'], options: MatchTask['options'], simulation?: MatchTask['simulation']): MatchTask => ({ ...b, kind: 'match', rows, options, ...(simulation ? { presentation: 'permissions' as const, simulation } : {}) });
const order = (b: TaskBase, items: OrderTask['items'], expected: string[], stepReasons: L[]): OrderTask => ({ ...b, kind: 'order', items, expected, stepReasons });
const effect = (label: L, rowId: string, allowedAnswers: string[], allowed: L, denied: L) => ({ label, checks: [{ rowId, allowedAnswers }], allowed, denied });
const meta = (slug: string, title: L, summary: L, topics: [L,L,L], outcomes: [L,L,L], reflection: L, teacherPrompt: L): Pick<Class9Chapter, 'slug'|'title'|'strand'|'summary'|'topics'|'outcomes'|'familyAction'|'reflection'|'teacherPrompt'|'rubric'> => ({
  slug, title, strand: 'Cybersecurity', summary, topics, outcomes, reflection, teacherPrompt,
  familyAction: l('With an adult, draw a plan for an invented club using only fictional records. Explain who needs each record and when access should end.', 'किसी बड़े के साथ केवल काल्पनिक रिकॉर्ड लेकर बनाए हुए क्लब की योजना बनाएँ। बताएँ कि किसे कौन-सा रिकॉर्ड चाहिए और एक्सेस कब खत्म हो।'),
  rubric: [l('Use supplied evidence to explain a risk and its consequence.', 'दिए गए सबूत से जोखिम और उसका परिणाम समझाएँ।'), l('Produce and test a complete practical record.', 'पूरा व्यावहारिक रिकॉर्ड बनाएँ और परखें।'), l('Revise the plan after a change and state a remaining limitation.', 'बदलाव के बाद योजना सुधारें और बची हुई सीमा बताएँ।')],
});

